import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const STATUS_TYPES = ['입·퇴사', '휴직', '근속연수', '가족', '학력·경력'];
// 가정: 접속 구분은 웹, 열람 대상 정보 유형은 현황 구분 이름으로 기록한다.
const LOGIN_TYPE = '웹';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function text(v: unknown): string | null {
  if (typeof v !== 'string') {
    return null;
  }
  const t = v.trim();
  return t === '' ? null : t;
}

function period(col: string): string {
  return '(' + col + ' IS NOT NULL'
    + ' AND (CAST(:startDate AS date) IS NULL OR ' + col + ' >= CAST(:startDate AS date))'
    + ' AND (CAST(:endDate AS date) IS NULL OR ' + col + ' <= CAST(:endDate AS date)))';
}

function build(q: Record<string, unknown>): { sql: string; params: Record<string, unknown>; statusType: string } {
  const statusType = text(q['statusType']);
  if (statusType === null) {
    throw new ApiError(422, 'STATUS_TYPE_REQUIRED', '현황 구분을 선택해 주세요.');
  }
  if (!STATUS_TYPES.includes(statusType)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '현황 구분 값이 올바르지 않습니다.');
  }
  const departmentId = text(q['departmentId']);
  if (departmentId !== null && !/^\d+$/.test(departmentId)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '주부서 형식이 올바르지 않습니다.');
  }
  const dates: Record<string, string | null> = {};
  for (const key of ['baseDate', 'startDate', 'endDate']) {
    const v = text(q[key]);
    if (v !== null && !/^\d{4}-\d{2}-\d{2}$/.test(v)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '날짜는 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    dates[key] = v;
  }
  const params: Record<string, unknown> = {
    departmentId,
    name: text(q['name']),
    baseDate: dates['baseDate'],
    startDate: dates['startDate'],
    endDate: dates['endDate'],
  };
  const cardTypes = statusType === '가족' ? "('가족')" : statusType === '학력·경력' ? "('학력', '경력')" : null;
  const itemCols = cardTypes !== null
    ? 'ci.item_type AS "itemType", ci.title AS "title"'
    : 'CAST(NULL AS varchar) AS "itemType", CAST(NULL AS varchar) AS "title"';
  const select = 'SELECT e.employee_id AS "employeeId", e.employee_no AS "employeeNo", e.name AS "name", '
    + 'e.department_id AS "departmentId", h.hire_date AS "hireDate", h.retirement_date AS "retirementDate", '
    + 'h.employment_status AS "employmentStatus", ' + itemCols + ', '
    + 'CASE WHEN h.hire_date IS NULL THEN NULL ELSE ROUND(CAST(COALESCE(CAST(:baseDate AS date), CURRENT_DATE) - h.hire_date AS numeric) / 365.25, 1) END AS "serviceYears"';
  let from = ' FROM employee e JOIN hr_record h ON h.employee_id = e.employee_id';
  if (cardTypes !== null) {
    from += ' JOIN hr_card_item ci ON ci.employee_id = e.employee_id AND ci.item_type IN ' + cardTypes;
  }
  const where: string[] = [
    '(CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))',
    "(CAST(:name AS varchar) IS NULL OR e.name LIKE '%' || CAST(:name AS varchar) || '%')",
  ];
  if (statusType === '입·퇴사') {
    where.push('(' + period('h.hire_date') + ' OR ' + period('h.retirement_date') + ')');
  } else if (statusType === '휴직') {
    where.push(
      "EXISTS (SELECT 1 FROM leave_absence_request l WHERE l.employee_id = e.employee_id AND l.request_type = '휴직' AND l.status = '승인'"
      + ' AND (CAST(:startDate AS date) IS NULL OR l.end_date >= CAST(:startDate AS date))'
      + ' AND (CAST(:endDate AS date) IS NULL OR l.start_date <= CAST(:endDate AS date)))',
    );
  } else if (statusType === '근속연수') {
    where.push('h.hire_date IS NOT NULL');
  }
  // 가정: 가족·학력·경력 현황에는 조회 기간을 적용하지 않는다.
  const order = cardTypes !== null ? ' ORDER BY e.employee_no, ci.hr_card_item_id' : ' ORDER BY e.employee_no, e.employee_id';
  return { sql: select + from + ' WHERE ' + where.join(' AND ') + order, params, statusType };
}

function csvCell(v: unknown): string {
  const s = v === null || v === undefined ? '' : String(v);
  return '"' + s.replace(/"/g, '""') + '"';
}

@Controller('api/v1')
export class FnSfr01403Controller {
  @Get('/hr-status')
  async listHrStatus(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자', '시스템 관리자');
    const q = checks.queryOf(req.query) as Record<string, unknown>;
    const built = build(q);
    const pageText = text(q['page']);
    const sizeText = text(q['size']);
    const page = pageText === null ? 0 : Number(pageText);
    const size = sizeText === null ? DEFAULT_SIZE : Number(sizeText);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기가 올바르지 않습니다.');
    }
    const limited = Math.min(size, MAX_SIZE);
    return transaction(async (db) => {
      const counted = await db.query('SELECT COUNT(*) AS "total" FROM (' + built.sql + ') t', built.params);
      const items = await db.query(
        built.sql + ' LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)',
        { ...built.params, limit: limited, offset: page * limited },
      );
      await db.execute(
        'INSERT INTO access_log (employee_id, event_type, accessed_at, login_ip, login_type, target_info_type, created_at, updated_at) '
        + "VALUES (CAST(:userId AS bigint), '개인정보열람', now(), :ip, :loginType, :targetInfoType, now(), now())",
        { userId: user.id, ip: req.ip || 'unknown', loginType: LOGIN_TYPE, targetInfoType: built.statusType },
      );
      return { items, page, size: limited, total: Number((counted[0] as Record<string, unknown>)['total']) };
    });
  }

  @Get('/hr-status/excel')
  async downloadHrStatusExcel(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자', '시스템 관리자');
    const q = checks.queryOf(req.query) as Record<string, unknown>;
    const built = build(q);
    return transaction(async (db) => {
      const rows = (await db.query(built.sql, built.params)) as Record<string, unknown>[];
      await db.execute(
        'INSERT INTO access_log (employee_id, event_type, accessed_at, login_ip, login_type, target_info_type, created_at, updated_at) '
        + "VALUES (CAST(:userId AS bigint), '개인정보열람', now(), :ip, :loginType, :targetInfoType, now(), now())",
        { userId: user.id, ip: req.ip || 'unknown', loginType: LOGIN_TYPE, targetInfoType: built.statusType },
      );
      const keys = ['employeeNo', 'name', 'departmentId', 'hireDate', 'retirementDate', 'employmentStatus', 'itemType', 'title', 'serviceYears'];
      const head = ['사번', '성명', '주부서', '입사일', '퇴직일', '재직 구분', '항목 유형', '항목명', '근속연수'];
      const lines = [head.map(csvCell).join(',')];
      for (const r of rows) {
        lines.push(keys.map((k) => csvCell(r[k])).join(','));
      }
      // 가정: 엑셀에서 열 수 있는 CSV(UTF-8 BOM 포함) 내용을 file 객체로 돌려준다.
      return {
        file: {
          fileName: 'hr-status.csv',
          contentType: 'text/csv; charset=utf-8',
          content: '\uFEFF' + lines.join('\r\n'),
        },
      };
    });
  }
}

