import { useState } from 'react';
import { Badge, Band, DataTable, DateInput, DateText, Drawer, ErrorText, Field, Filters, LookupSelect, Num, Pager, Pairs, RefName, Select, TextInput, call, useData } from '../kit';
import type { Column, Page, PageProps, Row } from '../kit';

const SIZE = 20;
const TYPES: [string, string][] = [
  ['입·퇴사', '입·퇴사'],
  ['휴직', '휴직'],
  ['근속연수', '근속연수'],
  ['가족', '가족'],
  ['학력·경력', '학력·경력'],
];

interface ExcelFile { file: { fileName: string; contentType: string; content: string } }

export default function FnSfr01403Page({ role, notify }: PageProps) {
  const [statusType, setStatusType] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [name, setName] = useState('');
  const [baseDate, setBaseDate] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [formError, setFormError] = useState('');

  const { data, error } = useData<Page | undefined>(async () => {
    if (applied === null) {
      return undefined;
    }
    return call<Page>('GET', '/hr-status', role, undefined, { ...applied, page, size: SIZE });
  }, [applied, page]);

  const search = () => {
    if (statusType === '') {
      setFormError('현황 구분을 선택해 주세요.');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied({ statusType, departmentId, name, baseDate, startDate, endDate });
  };

  const reset = () => {
    setStatusType('');
    setDepartmentId('');
    setName('');
    setBaseDate('');
    setStartDate('');
    setEndDate('');
    setApplied(null);
    setPage(0);
    setFormError('');
  };

  const download = async () => {
    if (applied === null) {
      setFormError('먼저 현황 구분을 선택해 조회해 주세요.');
      return;
    }
    try {
      setFormError('');
      const res = await call<ExcelFile>('GET', '/hr-status/excel', role, undefined, applied);
      const blob = new Blob([res.file.content], { type: res.file.contentType });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = res.file.fileName;
      a.click();
      URL.revokeObjectURL(url);
      notify('엑셀 파일을 내려받았습니다.');
    } catch (e) {
      setFormError(e instanceof Error ? e.message : '엑셀 다운로드에 실패했습니다.');
    }
  };

  const current = applied === null ? '' : String(applied['statusType']);
  const columns: Column[] = [
    { key: 'employeeNo', label: '사번' },
    { key: 'name', label: '성명' },
    { key: 'departmentId', label: '주부서', render: (r) => <RefName table="department" role={role} value={r['departmentId']} /> },
    { key: 'hireDate', label: '입사일', render: (r) => <DateText value={r['hireDate']} /> },
    { key: 'retirementDate', label: '퇴직일', render: (r) => <DateText value={r['retirementDate']} /> },
    { key: 'employmentStatus', label: '재직 구분', render: (r) => <Badge value={r['employmentStatus']} /> },
  ];
  if (current === '가족' || current === '학력·경력') {
    columns.push({ key: 'itemType', label: '항목 유형' });
    columns.push({ key: 'title', label: '항목명' });
  }
  if (current === '근속연수') {
    columns.push({ key: 'serviceYears', label: '근속연수', render: (r) => <Num value={r['serviceYears']} /> });
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <h1><Num value={data ? data.total : 0} /></h1>
        <p>{applied === null ? '현황 구분을 선택해 조회하세요.' : current + ' 현황'}</p>
      </section>
      <section className="box span-8">
        <h2>조회 조건</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="현황 구분" required>
            <Select value={statusType} onChange={setStatusType} options={TYPES} placeholder="선택" />
          </Field>
          <Field label="주부서">
            <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} />
          </Field>
          <Field label="성명">
            <TextInput value={name} onChange={setName} />
          </Field>
          <Field label="기준일" hint="근속연수 산정 기준">
            <DateInput value={baseDate} onChange={setBaseDate} />
          </Field>
          <Field label="조회 기간 시작">
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 기간 종료">
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
        </Filters>
        {formError !== '' && <ErrorText text={formError} />}
      </section>
      <section className="box span-12">
        <h2>인사현황 목록</h2>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={download}>엑셀 다운로드</button>
        </Band>
        {error !== '' && <ErrorText text={error} />}
        <DataTable
          columns={columns}
          rows={data ? data.items : []}
          onRowClick={(r) => setDetail(r)}
          empty={applied === null ? '현황 구분을 선택해 조회하세요.' : '조회 결과가 없습니다.'}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {detail !== null && (
        <Drawer title="인사현황 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['사번', String(detail['employeeNo'] ?? '')],
              ['성명', String(detail['name'] ?? '')],
              ['주부서', <RefName table="department" role={role} value={detail['departmentId']} />],
              ['입사일', <DateText value={detail['hireDate']} />],
              ['퇴직일', <DateText value={detail['retirementDate']} />],
              ['재직 구분', <Badge value={detail['employmentStatus']} />],
              ['항목 유형', String(detail['itemType'] ?? '')],
              ['항목명', String(detail['title'] ?? '')],
              ['근속연수', <Num value={detail['serviceYears']} />],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
